export const topics_3: readonly Topic[] = [
  { id: "public_ip", view: "network", tour: false,
    kw: ["public ip|my ip|ip address of my house|my internet address|what is my ip|isp|internet provider|who is my provider|asn", "ip publica|mi ip|direccion de mi casa en internet|mi direccion de internet|cual es mi ip|operador|proveedor de internet|quien es mi proveedor|asn", "öffentliche ip|meine ip|internetadresse meines hauses|meine internetadresse|wie lautet meine ip|anbieter|internetanbieter|wer ist mein anbieter|asn", "ip publique|mon ip|adresse de ma maison sur internet|mon adresse internet|quelle est mon ip|opérateur|fournisseur d accès|qui est mon fournisseur|asn", "ip pubblico|il mio ip|indirizzo della mia casa su internet|il mio indirizzo internet|qual è il mio ip|operatore|provider internet|chi è il mio provider|asn", "公開ip|自分のip|家のインターネットアドレス|インターネットのアドレス|ipは何|プロバイダー|通信事業者|asn", "公网ip|我的ip|我家的互联网地址|我的互联网地址|我的ip是什么|运营商|网络提供商|asn", "ip público|o meu ip|endereço da minha casa na internet|o meu endereço de internet|qual é o meu ip|operador|fornecedor de internet|quem é o meu fornecedor|asn"],
    q: ["What is my public IP?", "¿Cuál es mi IP pública?", "Wie lautet meine öffentliche IP?", "Quelle est mon IP publique ?", "Qual è il mio IP pubblico?", "自分の公開IPは何ですか？", "我的公网 IP 是什么？", "Qual é o meu IP público?"],
    a: ["Open Network: right under the internet state there is a card with your public IP (with a button to copy it), your provider and its network number (ASN), the place with its flag, the time there, whether it is IPv4 or IPv6, and since when the address has not changed. It comes from the network node, which asks one public service now and then.",
        "Abre Red: justo bajo el estado de internet hay una tarjeta con tu IP pública (con un botón para copiarla), tu operador y su número de red (ASN), el lugar con su bandera, la hora allí, si es IPv4 o IPv6 y desde cuándo no ha cambiado la dirección. Viene del nodo de red, que consulta de vez en cuando un servicio público.",
        "Öffnen Sie Netzwerk: direkt unter dem Internetstatus steht eine Karte mit Ihrer öffentlichen IP (mit Kopierschaltfläche), Ihrem Anbieter und seiner Netznummer (ASN), dem Ort mit Flagge, der Uhrzeit dort, ob es IPv4 oder IPv6 ist und seit wann sich die Adresse nicht geändert hat. Sie stammt vom Netzwerk-Knoten, der ab und zu einen öffentlichen Dienst abfragt.",
        "Ouvrez Réseau : juste sous l'état d'internet, une carte montre votre IP publique (avec un bouton pour la copier), votre opérateur et son numéro de réseau (ASN), le lieu avec son drapeau, l'heure là-bas, s'il s'agit d'IPv4 ou d'IPv6 et depuis quand l'adresse n'a pas changé. Elle vient du nœud réseau, qui interroge de temps en temps un service public.",
        "Apri Rete: subito sotto lo stato di internet c'è una scheda con il tuo IP pubblico (con un pulsante per copiarlo), il tuo operatore e il suo numero di rete (ASN), il luogo con la sua bandiera, l'ora lì, se è IPv4 o IPv6 e da quando l'indirizzo non è cambiato. Arriva dal nodo di rete, che ogni tanto interroga un servizio pubblico.",
        "「ネットワーク」を開くと、インターネット状態のすぐ下に、公開IP（コピーボタンつき）、プロバイダーとネットワーク番号（ASN）、国旗つきの場所、現地時刻、IPv4かIPv6か、アドレスが変わっていない期間を示すカードがあります。ネットワークノードが時々公開サービスに問い合わせた結果です。",
        "打开“网络”：在互联网状态正下方有一张卡片，显示您的公网 IP（带复制按钮）、运营商及网络编号（ASN）、带国旗的地点、当地时间、IPv4 还是 IPv6，以及该地址已多久未变。数据来自网络节点，它会不时查询一个公共服务。",
        "Abra Rede: mesmo por baixo do estado da internet há um cartão com o seu IP público (com um botão para o copiar), o seu operador e o seu número de rede (ASN), o local com a sua bandeira, a hora lá, se é IPv4 ou IPv6 e desde quando o endereço não mudou. Vem do nó de rede, que consulta de vez em quando um serviço público."] },
  { id: "auto_capture", view: "configuration", tour: false,
    kw: ["automatic capture|auto capture|photo when|video when|record when|take a photo when|capture when something|how long is the video|how many photos|photos every", "captura automatica|foto cuando|video cuando|grabar cuando|hacer una foto cuando|capturar cuando|cuanto dura el video|cuantas fotos|fotos cada", "automatische aufnahme|foto wenn|video wenn|aufnehmen wenn|wie lange dauert das video|wie viele fotos|fotos alle", "capture automatique|photo quand|video quand|enregistrer quand|combien de temps dure la video|combien de photos|photos toutes les", "cattura automatica|foto quando|video quando|registrare quando|quanto dura il video|quante foto|foto ogni", "自動撮影|検知したら写真|検知したら録画|動画の長さ|写真の枚数|写真を何秒ごと", "自动抓拍|检测到时拍照|检测到时录像|视频时长|照片数量|每隔几秒拍照", "captura automatica|foto quando|video quando|gravar quando|quanto dura o video|quantas fotos|fotos de"],
    q: ["How do I make the cameras take a photo and a video when they see something?", "¿Cómo hago que las cámaras hagan foto y vídeo cuando ven algo?", "Wie sorge ich dafür, dass die Kameras ein Foto und ein Video machen, wenn sie etwas sehen?", "Comment faire que les caméras prennent une photo et une vidéo quand elles voient quelque chose ?", "Come faccio in modo che le telecamere scattino una foto e un video quando vedono qualcosa?", "カメラが何かを検知したときに写真と動画を撮るには？", "怎么让摄像头发现情况时自动拍照和录像？", "Como faço para as câmaras tirarem foto e vídeo quando veem algo?"],
    a: ["Open Configuration > Automatic capture (an administrator): with the system armed, when a camera sees something the server takes a photo and a video by itself. You choose how many photos and how far apart (up to 60, one to 300 seconds), how many seconds of video (3 to 300) and how long a camera is left alone afterwards. They appear in Record.",
        "Abre Configuración > Captura automática (un administrador): con el sistema armado, cuando una cámara ve algo el servidor hace por sí solo una foto y un vídeo. Eliges cuántas fotos y con cuánta separación (hasta 60, de uno a 300 segundos), cuántos segundos de vídeo (de 3 a 300) y cuánto se deja tranquila la cámara después. Aparecen en Grabaciones.",
        "Öffnen Sie Konfiguration > Automatische Aufnahme (Administrator): Bei scharfem System macht der Server, wenn eine Kamera etwas sieht, selbst ein Foto und ein Video. Sie wählen, wie viele Fotos und mit welchem Abstand (bis zu 60, ein bis 300 Sekunden), wie viele Sekunden Video (3 bis 300) und wie lange die Kamera danach in Ruhe gelassen wird. Sie erscheinen unter Aufnahmen.",
        "Ouvrez Configuration > Capture automatique (administrateur) : le système étant armé, quand une caméra voit quelque chose le serveur prend lui-même une photo et une vidéo. Vous choisissez combien de photos et à quel intervalle (jusqu'à 60, d'une à 300 secondes), combien de secondes de vidéo (de 3 à 300) et combien de temps la caméra est ensuite laissée tranquille. Elles apparaissent dans Enregistrements.",
        "Apri Configurazione > Cattura automatica (amministratore): a sistema inserito, quando una telecamera vede qualcosa il server fa da solo una foto e un video. Scegli quante foto e a che distanza (fino a 60, da uno a 300 secondi), quanti secondi di video (da 3 a 300) e per quanto la telecamera viene poi lasciata in pace. Compaiono in Registrazioni.",
        "「設定 > 自動撮影」（管理者）を開きます。警戒中にカメラが何かを検知すると、サーバーが自動で写真と動画を撮ります。写真の枚数と間隔（最大60枚、1〜300秒）、動画の長さ（3〜300秒）、撮影後にカメラを放置する時間を選べます。結果は「記録」に表示されます。",
        "打开“配置 > 自动抓拍”（管理员）：系统布防时，摄像头发现情况，服务器会自动拍照并录像。可选择照片数量和间隔（最多 60 张，间隔 1 到 300 秒）、视频时长（3 到 300 秒）以及抓拍后摄像头被搁置的时间。结果显示在“录像”中。",
        "Abra Configuração > Captura automática (administrador): com o sistema armado, quando uma câmara vê algo o servidor tira sozinho uma foto e grava um vídeo. Escolhe quantas fotos e com que intervalo (até 60, de um a 300 segundos), quantos segundos de vídeo (de 3 a 300) e durante quanto tempo a câmara é depois deixada em paz. Aparecem em Gravações."] },
  { id: "assistant_move", view: "configuration", tour: false,
    kw: ["move the assistant|move the mascot|drag the assistant|pin the assistant|anchor the assistant|assistant in the way|assistant is covering|resize the assistant|make the assistant bigger|make the assistant smaller", "mover el asistente|mover la mascota|arrastrar el asistente|anclar el asistente|fijar el asistente|el asistente tapa|cambiar el tamano del asistente|asistente mas grande|asistente mas pequeno", "assistenten verschieben|maskottchen verschieben|assistenten ziehen|assistenten fixieren|assistent verdeckt|größe des assistenten|assistent größer|assistent kleiner", "deplacer l assistant|deplacer la mascotte|faire glisser l assistant|epingler l assistant|l assistant gene|taille de l assistant|assistant plus grand|assistant plus petit", "spostare l assistente|spostare la mascotte|trascinare l assistente|fissare l assistente|l assistente copre|dimensione dell assistente|assistente piu grande|assistente piu piccolo", "アシスタントを動かす|アシスタントをドラッグ|アシスタントを固定|アシスタントが邪魔|アシスタントの大きさ|マスコットを動かす", "移动助手|拖动助手|固定助手|助手挡住|助手的大小|移动吉祥物", "mover o assistente|mover a mascote|arrastar o assistente|fixar o assistente|o assistente tapa|tamanho do assistente|assistente maior|assistente menor"],
    q: ["How do I move the assistant or pin it where I want?", "¿Cómo muevo el asistente o lo anclo donde quiero?", "Wie verschiebe ich den Assistenten oder fixiere ihn, wo ich will?", "Comment déplacer l'assistant ou l'épingler où je veux ?", "Come sposto l'assistente o lo fisso dove voglio?", "アシスタントを動かしたり好きな場所に固定するには？", "怎么移动助手或把它固定在想要的位置？", "Como movo o assistente ou o fixo onde quero?"],
    a: ["Drag the mascot anywhere in the window (the arrow keys move it too). Then press \"Pin here\" in its bubble, or switch on \"Pin the assistant\" in Configuration > Preferences: it stays there and no longer follows the menus. There you can also choose its size, stop its bubble from opening by itself and put it back in its place. The bubble opens on the side of the mascot that has room (right, left, above, below or diagonally), so it never goes out of the window.",
        "Arrastra la mascota a cualquier punto de la ventana (con las flechas del teclado también se mueve). Luego pulsa \"Anclar aquí\" en su globo, o activa \"Anclar el asistente\" en Configuración > Preferencias: se queda ahí y ya no sigue a los menús. Allí también eliges su tamaño, evitas que abra su globo solo y lo devuelves a su sitio. El globo se abre en el lado de la mascota que tiene sitio (derecha, izquierda, arriba, abajo o en diagonal), así que nunca se sale de la ventana.",
        "Ziehen Sie das Maskottchen an eine beliebige Stelle des Fensters (die Pfeiltasten bewegen es ebenfalls). Drücken Sie dann in seiner Sprechblase \"Hier fixieren\" oder aktivieren Sie \"Assistenten an seinem Platz fixieren\" unter Konfiguration > Einstellungen: Er bleibt dort und folgt den Menüs nicht mehr. Dort wählen Sie auch seine Größe, verhindern, dass seine Sprechblase von selbst aufgeht, und setzen ihn zurück. Die Sprechblase öffnet sich auf der Seite des Maskottchens, wo Platz ist (rechts, links, oben, unten oder diagonal), und verlässt so nie das Fenster.",
        "Faites glisser la mascotte n'importe où dans la fenêtre (les flèches du clavier la déplacent aussi). Puis appuyez sur « Épingler ici » dans sa bulle, ou activez « Épingler l'assistant où il est » dans Configuration > Préférences : il reste là et ne suit plus les menus. Vous y choisissez aussi sa taille, l'empêchez d'ouvrir sa bulle tout seul et le remettez à sa place. La bulle s'ouvre du côté de la mascotte où il y a de la place (droite, gauche, haut, bas ou en diagonale) et ne sort donc jamais de la fenêtre.",
        "Trascina la mascotte in qualsiasi punto della finestra (anche i tasti freccia la spostano). Poi premi \"Fissa qui\" nel suo fumetto, o attiva \"Fissa l'assistente dove si trova\" in Configurazione > Preferenze: resta lì e non segue più i menu. Lì scegli anche la dimensione, eviti che apra da solo il fumetto e lo rimetti al suo posto. Il fumetto si apre dal lato della mascotte che ha spazio (destra, sinistra, sopra, sotto o in diagonale), così non esce mai dalla finestra.",
        "マスコットをウィンドウの好きな場所へドラッグします（矢印キーでも移動できます）。吹き出しの「ここに固定」か、「設定 > 設定項目」の「アシスタントを今の場所に固定」をオンにすると、その場所に留まりメニューに付いてこなくなります。そこで大きさの変更、吹き出しの自動表示の停止、元の位置への復帰もできます。 吹き出しはマスコットの空いている側（右・左・上・下・斜め）に開くため、ウィンドウの外にはみ出しません。",
        "把吉祥物拖到窗口的任意位置（方向键同样可移动）。然后点击其气泡中的“固定在此”，或在“配置 > 偏好”中开启“将助手固定在当前位置”：它会留在那里，不再跟随菜单。在那里还可以选择它的大小、禁止气泡自动弹出，并将它放回原位。 气泡会在吉祥物有空位的一侧（右、左、上、下或对角）打开，因此不会超出窗口。",
        "Arraste a mascote para qualquer ponto da janela (as setas do teclado também a movem). Depois prima \"Fixar aqui\" no seu balão, ou ative \"Fixar o assistente onde está\" em Configuração > Preferências: fica lá e já não segue os menus. Aí escolhe também o tamanho, evita que abra o balão sozinho e devolve-o ao seu lugar. O balão abre-se do lado da mascote que tem espaço (direita, esquerda, cima, baixo ou na diagonal), por isso nunca sai da janela."] },
  { id: "ignore_zones", view: "configuration", tour: false,
    kw: ["ignore a zone|ignore zone|ignore the tree|false alarms from a tree|camera keeps detecting|mask the picture|exclude an area|a tree sets off the alarm|ignore part of the picture", "ignorar una zona|zona a ignorar|ignorar el arbol|falsas alarmas por un arbol|la camara detecta siempre|enmascarar la imagen|excluir una zona|un arbol dispara la alarma|ignorar parte de la imagen", "zone ignorieren|zonen ignorieren|baum ignorieren|fehlalarme durch einen baum|kamera erkennt ständig|bild maskieren|bereich ausschließen|ein baum löst den alarm aus|teil des bildes ignorieren", "ignorer une zone|zone a ignorer|ignorer l arbre|fausses alarmes a cause d un arbre|la camera detecte tout le temps|masquer l image|exclure une zone|un arbre declenche l alarme|ignorer une partie de l image", "ignorare una zona|zona da ignorare|ignorare l albero|falsi allarmi per un albero|la telecamera rileva sempre|mascherare l immagine|escludere un area|un albero fa scattare l allarme|ignorare parte dell immagine", "ゾーンを無視|無視するゾーン|木を無視|木で誤報|カメラが常に検知|画像をマスク|領域を除外|映像の一部を無視", "忽略区域|忽略树|树引起误报|摄像头总是检测到|屏蔽画面|排除区域|忽略部分画面", "ignorar uma zona|zona a ignorar|ignorar a árvore|falsos alarmes por causa de uma árvore|a câmara deteta sempre|mascarar a imagem|excluir uma zona|uma árvore dispara o alarme|ignorar parte da imagem"],
    q: ["A tree keeps setting off the alarm: how do I ignore that part of the picture?", "Un árbol dispara siempre la alarma: ¿cómo ignoro esa parte de la imagen?", "Ein Baum löst ständig den Alarm aus: Wie ignoriere ich diesen Teil des Bildes?", "Un arbre déclenche toujours l'alarme : comment ignorer cette partie de l'image ?", "Un albero fa sempre scattare l'allarme: come ignoro quella parte dell'immagine?", "木が何度もアラームを鳴らします。その部分の画像を無視するには？", "有棵树总是触发报警：怎么忽略画面的这一部分？", "Uma árvore dispara sempre o alarme: como ignoro essa parte da imagem?"],
    a: ["Open Configuration > Cameras, choose the camera and, under its settings, drag rectangles over the parts of the live picture to ignore (up to sixteen), then save. The observation service leaves those pixels out of its movement detection; the video, photos and recordings stay whole.",
        "Abre Configuración > Cámaras, elige la cámara y, bajo sus ajustes, arrastra rectángulos sobre las partes de la imagen en vivo que quieres ignorar (hasta dieciséis) y guarda. El servicio de observación deja esos píxeles fuera de su detección de movimiento; el vídeo, las fotos y las grabaciones se quedan enteros.",
        "Öffnen Sie Konfiguration > Kameras, wählen Sie die Kamera und ziehen Sie unter ihren Einstellungen Rechtecke über die zu ignorierenden Teile des Live-Bildes (bis zu sechzehn), dann speichern. Der Beobachtungsdienst lässt diese Pixel bei der Bewegungserkennung aus; Video, Fotos und Aufnahmen bleiben vollständig.",
        "Ouvrez Configuration > Caméras, choisissez la caméra et, sous ses réglages, faites glisser des rectangles sur les parties de l'image en direct à ignorer (jusqu'à seize), puis enregistrez. Le service d'observation laisse ces pixels hors de sa détection de mouvement ; la vidéo, les photos et les enregistrements restent entiers.",
        "Apri Configurazione > Telecamere, scegli la telecamera e, sotto le sue impostazioni, trascina rettangoli sulle parti dell'immagine in diretta da ignorare (fino a sedici), poi salva. Il servizio di osservazione lascia quei pixel fuori dal rilevamento del movimento; il video, le foto e le registrazioni restano interi.",
        "「設定 > カメラ」でカメラを選び、その設定の下で、無視したいライブ映像の部分に四角形をドラッグ（最大16個）して保存します。観測サービスはそのピクセルを動体検知から除外します。映像・写真・録画はそのままです。",
        "打开“配置 > 摄像头”，选择该摄像头，在其设置下方的实时画面上把要忽略的部分拖出矩形（最多十六个）并保存。观察服务会在移动检测中忽略这些像素；视频、照片和录像保持完整。",
        "Abra Configuração > Câmaras, escolha a câmara e, por baixo das suas definições, arraste retângulos sobre as partes da imagem em direto a ignorar (até dezasseis) e guarde. O serviço de observação deixa esses píxeis fora da sua deteção de movimento; o vídeo, as fotos e as gravações ficam inteiros."] },
  { id: "firmware_signature", view: "configuration", tour: false,
    kw: ["firmware signature|signed firmware|signature is not valid|bad signature|no signature|node refuses firmware|firmware refused|firmware rejected|refuse firmware update|refuses a firmware update", "firma del firmware|firmware firmado|firma no valida|firma no es valida|sin firma|nodo rechaza el firmware|firmware rechazado|rechaza la actualizacion|rechaza una actualizacion de firmware", "firmware signatur|signierte firmware|signatur ungueltig|keine signatur|knoten lehnt firmware ab|firmware abgelehnt|lehnt ein firmware update ab", "signature du firmware|firmware signe|signature invalide|signature pas valide|sans signature|noeud refuse le firmware|firmware refuse|refuse une mise a jour du firmware", "firma del firmware|firmware firmato|firma non valida|senza firma|nodo rifiuta il firmware|firmware rifiutato|rifiuta un aggiornamento del firmware", "ファームウェア署名|署名済みファームウェア|署名が無効|署名がない|ファームウェア更新を拒否|ファームウェアを拒否", "固件签名|已签名固件|签名无效|没有签名|拒绝固件更新|拒绝固件", "assinatura do firmware|firmware assinado|assinatura nao e valida|assinatura invalida|sem assinatura|no recusa o firmware|firmware recusado|recusa uma atualizacao de firmware"],
    q: ["Why does a node refuse a firmware update (signature)?", "¿Por qué un nodo rechaza una actualización de firmware (firma)?", "Warum lehnt ein Knoten ein Firmware-Update ab (Signatur)?", "Pourquoi un nœud refuse-t-il une mise à jour du firmware (signature) ?", "Perché un nodo rifiuta un aggiornamento del firmware (firma)?", "ノードがファームウェア更新を拒否するのはなぜ？（署名）", "为什么节点拒绝固件更新（签名）？", "Porque é que um nó recusa uma atualização de firmware (assinatura)?"],
    a: ["The nodes only install from GitHub a firmware that the maintainer signed (Ed25519). If a node says the signature is missing or not valid, it refused the file and nothing changed: wait for the signed release or, as an administrator, upload the firmware file by hand in the node's own panel (Firmware tab), which is always allowed. The signing key never leaves the maintainer.",
        "Los nodos solo instalan desde GitHub un firmware firmado por el responsable (Ed25519). Si un nodo dice que falta la firma o que no es válida, rechazó el archivo y no cambió nada: espera a la versión firmada o, como administrador, sube el archivo de firmware a mano en el panel del propio nodo (pestaña Firmware), que siempre está permitido. La clave de firma nunca sale del responsable.",
        "Die Knoten installieren von GitHub nur eine Firmware, die der Betreuer signiert hat (Ed25519). Meldet ein Knoten, die Signatur fehle oder sei ungültig, hat er die Datei abgelehnt und nichts hat sich geändert: Warten Sie auf die signierte Version oder laden Sie als Administrator die Firmware-Datei von Hand im Panel des Knotens hoch (Reiter Firmware), was immer erlaubt ist. Der Signaturschlüssel verlässt den Betreuer nie.",
        "Les nœuds n'installent depuis GitHub qu'un firmware signé par le responsable (Ed25519). Si un nœud indique que la signature manque ou n'est pas valide, il a refusé le fichier et rien n'a changé : attendez la version signée ou, en tant qu'administrateur, envoyez le fichier de firmware à la main dans le panneau du nœud (onglet Firmware), ce qui est toujours permis. La clé de signature ne quitte jamais le responsable.",
        "I nodi installano da GitHub solo un firmware firmato dal responsabile (Ed25519). Se un nodo dice che la firma manca o non è valida, ha rifiutato il file e non è cambiato nulla: attendi la versione firmata oppure, da amministratore, carica a mano il file di firmware nel pannello del nodo (scheda Firmware), cosa sempre consentita. La chiave di firma non lascia mai il responsabile.",
        "ノードがGitHubからインストールするのは、管理者がEd25519で署名したファームウェアだけです。署名がない、または無効とノードが表示した場合、そのファイルは拒否されており何も変わっていません。署名済みリリースを待つか、管理者としてノード自身のパネル（ファームウェアタブ）から手動でファームウェアファイルをアップロードしてください（常に許可されています）。署名鍵は管理者の手元から出ません。",
        "节点只会从 GitHub 安装由维护者签名（Ed25519）的固件。如果节点提示签名缺失或无效，说明它拒绝了该文件，没有任何改动：请等待已签名的版本，或以管理员身份在节点自己的面板（固件标签页）中手动上传固件文件（始终允许）。签名密钥从不离开维护者。",
        "Os nós só instalam do GitHub um firmware assinado pelo responsável (Ed25519). Se um nó disser que a assinatura falta ou não é válida, recusou o ficheiro e nada mudou: espere pela versão assinada ou, como administrador, carregue o ficheiro de firmware à mão no painel do próprio nó (separador Firmware), o que é sempre permitido. A chave de assinatura nunca sai do responsável."] },
  { id: "node_ota", view: "configuration", tour: false,
    kw: ["firmware slot|firmware slots|spare slot|two slots|rollback|roll back|does not start after update|new firmware does not start|ota|over the air", "ranura de firmware|ranuras de firmware|dos ranuras|vuelta atras|el firmware nuevo no arranca|no arranca tras la actualizacion|ota|por el aire", "firmware-slot|firmware-slots|zwei slots|rueckfall|neue firmware startet nicht|startet nicht nach dem update|ota|per funk", "emplacement de firmware|emplacements de firmware|deux emplacements|retour arriere|le nouveau firmware ne demarre pas|ne demarre pas apres la mise a jour|ota|par voie hertzienne", "slot del firmware|due slot|ripristino|il nuovo firmware non parte|non parte dopo l'aggiornamento|ota|via etere", "ファームウェアスロット|2つのスロット|ロールバック|新しいファームウェアが起動しない|更新後に起動しない|ota", "固件分区|两个分区|回滚|新固件无法启动|更新后无法启动|ota|无线更新", "ranhura de firmware|ranhuras de firmware|duas ranhuras|retrocesso|o firmware novo nao arranca|nao arranca apos a atualizacao|ota|pelo ar"],
    q: ["What happens if the new firmware of a node does not start (slots, rollback)?", "¿Qué pasa si el firmware nuevo de un nodo no arranca (ranuras, vuelta atrás)?", "Was passiert, wenn die neue Firmware eines Knotens nicht startet (Slots, Rückfall)?", "Que se passe-t-il si le nouveau firmware d'un nœud ne démarre pas (emplacements, retour arrière) ?", "Cosa succede se il nuovo firmware di un nodo non parte (slot, ripristino)?", "ノードの新しいファームウェアが起動しないとどうなる？（スロット、ロールバック）", "节点的新固件无法启动会怎样（分区、回滚）？", "O que acontece se o firmware novo de um nó não arrancar (ranhuras, retrocesso)?"],
    a: ["Each node keeps its firmware in two slots of its 16 MB flash. An update, sent from Configuration > Node firmware or from the node's own panel, is written into the spare slot while the running one is untouched, and the node switches to it only if the image is valid (right SHA-256, and from GitHub a valid Ed25519 signature of the maintainer). If the new firmware then does not start, the node goes back to the previous one by itself, so a bad update does not leave a dead node. The node's Overview page says what the two slots hold and which one runs. After the update the node restarts and Studio waits for it to come back with the new version.",
        "Cada nodo guarda su firmware en dos ranuras de sus 16 MB de flash. Una actualización, enviada desde Configuración > Firmware de nodos o desde el panel del propio nodo, se escribe en la ranura libre sin tocar la que está en marcha, y el nodo cambia a ella solo si la imagen es válida (SHA-256 correcto y, desde GitHub, una firma Ed25519 válida del responsable). Si el firmware nuevo no arranca, el nodo vuelve solo al anterior, así que una mala actualización no deja un nodo muerto. La página Resumen del nodo dice qué guardan las dos ranuras y cuál se ejecuta. Tras la actualización el nodo se reinicia y Studio espera a que vuelva con la versión nueva.",
        "Jeder Knoten hält seine Firmware in zwei Slots seines 16-MB-Flashs. Ein Update, gesendet unter Konfiguration > Knoten-Firmware oder aus dem eigenen Panel des Knotens, wird in den freien Slot geschrieben, ohne den laufenden anzutasten, und der Knoten wechselt nur dorthin, wenn das Abbild gültig ist (richtiger SHA-256 und von GitHub eine gültige Ed25519-Signatur des Betreuers). Startet die neue Firmware danach nicht, kehrt der Knoten von selbst zur vorigen zurück, ein schlechtes Update hinterlässt also keinen toten Knoten. Die Übersichtsseite des Knotens zeigt, was die beiden Slots enthalten und welcher läuft. Nach dem Update startet der Knoten neu, und Studio wartet, bis er mit der neuen Version zurückkommt.",
        "Chaque nœud garde son firmware dans deux emplacements de ses 16 Mo de flash. Une mise à jour, envoyée depuis Configuration > Firmware des nœuds ou depuis le panneau du nœud, s'écrit dans l'emplacement libre sans toucher celui qui tourne, et le nœud n'y bascule que si l'image est valide (bon SHA-256 et, depuis GitHub, une signature Ed25519 valide du mainteneur). Si le nouveau firmware ne démarre pas, le nœud revient seul au précédent : une mauvaise mise à jour ne laisse pas un nœud mort. La page Aperçu du nœud dit ce que contiennent les deux emplacements et lequel tourne. Après la mise à jour le nœud redémarre et Studio attend qu'il revienne avec la nouvelle version.",
        "Ogni nodo tiene il firmware in due slot dei suoi 16 MB di flash. Un aggiornamento, inviato da Configurazione > Firmware dei nodi o dal pannello del nodo, viene scritto nello slot libero senza toccare quello in esecuzione, e il nodo vi passa solo se l'immagine è valida (SHA-256 giusto e, da GitHub, una firma Ed25519 valida del responsabile). Se il nuovo firmware non parte, il nodo torna da solo al precedente, quindi un aggiornamento sbagliato non lascia un nodo morto. La pagina Panoramica del nodo dice cosa contengono i due slot e quale è in esecuzione. Dopo l'aggiornamento il nodo si riavvia e Studio attende che torni con la nuova versione.",
        "各ノードは16MBフラッシュの2つのスロットにファームウェアを保持します。「設定 > ノードファームウェア」またはノード自身のパネルから送った更新は、動作中のスロットに触れずに空いているスロットへ書き込まれ、イメージが有効なとき（正しいSHA-256、GitHubからの場合はメンテナーの有効なEd25519署名）だけノードが切り替えます。新しいファームウェアが起動しなければノードは自動で前の版に戻るので、失敗した更新でノードが動かなくなることはありません。ノードの概要ページで2つのスロットの中身と実行中のスロットが分かります。更新後ノードは再起動し、Studioは新バージョンで戻るのを待ちます。",
        "每个节点把固件保存在其 16 MB 闪存的两个分区中。通过“配置 > 节点固件”或节点自己的面板发送的更新，会写入备用分区而不动正在运行的那个；只有镜像有效时（SHA-256 正确，来自 GitHub 的还要有维护者有效的 Ed25519 签名）节点才会切换过去。如果新固件无法启动，节点会自动回到之前的版本，因此一次失败的更新不会留下一个“死”节点。节点的概览页会显示两个分区各存了什么以及哪个在运行。更新后节点重启，Studio 等它以新版本重新上线。",
        "Cada nó guarda o firmware em duas ranhuras dos seus 16 MB de flash. Uma atualização, enviada de Configuração > Firmware dos nós ou do painel do próprio nó, é escrita na ranhura livre sem tocar na que está a correr, e o nó só passa para ela se a imagem for válida (SHA-256 certo e, a partir do GitHub, uma assinatura Ed25519 válida do responsável). Se o firmware novo não arrancar, o nó volta sozinho ao anterior, por isso uma má atualização não deixa um nó morto. A página Resumo do nó diz o que guardam as duas ranhuras e qual corre. Após a atualização o nó reinicia e o Studio espera que volte com a versão nova."] },
  { id: "node_wifi", view: "radar", tour: false,
    kw: ["access point|node access point|one wifi from many nodes|same network name|station mode|join the router wifi|node without cable|no cable|armor-setup|192.168.4.1|channel automatic", "punto de acceso|punto de acceso del nodo|un wifi con varios nodos|mismo nombre de red|modo estacion|unirse al wifi del router|nodo sin cable|sin cable|armor-setup|192.168.4.1|canal automatico", "zugangspunkt|zugangspunkt des knotens|ein wlan aus mehreren knoten|gleicher netzname|stationsmodus|ins router-wlan|knoten ohne kabel|ohne kabel|armor-setup|192.168.4.1|kanal automatisch", "point d'acces|point d'acces du noeud|un wifi avec plusieurs noeuds|meme nom de reseau|mode station|rejoindre le wifi du routeur|noeud sans cable|sans cable|armor-setup|192.168.4.1|canal automatique", "punto di accesso|punto di accesso del nodo|un wifi da piu nodi|stesso nome di rete|modalita stazione|collegarsi al wifi del router|nodo senza cavo|senza cavo|armor-setup|192.168.4.1|canale automatico", "アクセスポイント|ノードのアクセスポイント|複数ノードで1つのwifi|同じネットワーク名|ステーションモード|ルーターのwifiに参加|ケーブルなしのノード|armor-setup|192.168.4.1|チャンネル自動", "接入点|节点的接入点|多个节点组成一个wifi|相同的网络名称|终端模式|加入路由器wifi|没有网线的节点|无网线|armor-setup|192.168.4.1|信道自动", "ponto de acesso|ponto de acesso do no|um wifi com varios nos|mesmo nome de rede|modo estacao|juntar-se ao wifi do router|no sem cabo|sem cabo|armor-setup|192.168.4.1|canal automatico"],
    q: ["How do the nodes make one Wi-Fi network, and how does a node with no cable join mine?", "¿Cómo forman los nodos un solo Wi-Fi y cómo se une a la mía un nodo sin cable?", "Wie bilden die Knoten ein WLAN, und wie tritt ein Knoten ohne Kabel meinem bei?", "Comment les nœuds forment-ils un seul Wi-Fi et comment un nœud sans câble rejoint-il le mien ?", "Come formano i nodi un solo Wi-Fi e come si collega alla mia rete un nodo senza cavo?", "ノードで1つのWi-Fiを作る方法と、ケーブルのないノードを自分のWi-Fiに参加させる方法は？", "节点如何组成一个 Wi-Fi，没有网线的节点怎样加入我的 Wi-Fi？", "Como formam os nós um só Wi-Fi e como se junta à minha um nó sem cabo?"],
    a: ["In the node's panel, Wi-Fi page, a node can do two things. As an access point it offers its own network, joined to its Ethernet port: give several nodes the same network name, security and password, leave the channel on automatic (each picks 1, 6 or 11 from its MAC) and connect them to the same switch, and phones and Wi-Fi sensors see one network with one DHCP server. It is not a radio mesh: every node keeps its cable, serves up to ten clients and has the speed of a small microcontroller, so it is for sensors and configuration, not for the household's Internet. As a station, the node joins your router's Wi-Fi (the page can search for networks), which is the way for a node with no cable. A node with no user, or one that is set up but still has no address 90 seconds after starting, opens the Wi-Fi ARMOR-SETUP-xxxxxx (password: the set-up code) and answers at http://192.168.4.1. Use WPA2 or WPA3 with a real password: the clients of the access point are on the same network as the broker.",
        "En el panel del nodo, página Wi-Fi, un nodo puede hacer dos cosas. Como punto de acceso ofrece su propia red, unida a su puerto Ethernet: da a varios nodos el mismo nombre de red, seguridad y contraseña, deja el canal en automático (cada uno elige 1, 6 u 11 según su MAC) y conéctalos al mismo conmutador, y los móviles y sensores Wi-Fi ven una red con un servidor DHCP. No es una malla de radio: cada nodo conserva su cable, atiende hasta diez clientes y tiene la velocidad de un microcontrolador pequeño, así que sirve para sensores y configuración, no para el internet de la casa. Como estación, el nodo se une al Wi-Fi de tu router (la página puede buscar redes), que es el camino de un nodo sin cable. Un nodo sin usuario, o uno configurado que 90 segundos después de arrancar aún no tiene dirección, abre el Wi-Fi ARMOR-SETUP-xxxxxx (contraseña: el código de configuración) y responde en http://192.168.4.1. Usa WPA2 o WPA3 con una contraseña de verdad: los clientes del punto de acceso están en la misma red que el broker.",
        "Im Panel des Knotens kann ein Knoten auf der WLAN-Seite zweierlei. Als Zugangspunkt bietet er ein eigenes Netz an, verbunden mit seinem Ethernet-Port: Geben Sie mehreren Knoten denselben Netznamen, dieselbe Sicherheit und dasselbe Passwort, lassen Sie den Kanal auf automatisch (jeder wählt 1, 6 oder 11 nach seiner MAC) und verbinden Sie sie mit demselben Switch, dann sehen Handys und WLAN-Sensoren ein Netz mit einem DHCP-Server. Es ist kein Funk-Mesh: Jeder Knoten behält sein Kabel, bedient bis zu zehn Clients und hat die Geschwindigkeit eines kleinen Mikrocontrollers, taugt also für Sensoren und Konfiguration, nicht für das Internet des Haushalts. Als Station tritt der Knoten dem WLAN Ihres Routers bei (die Seite kann Netze suchen), so arbeitet ein Knoten ohne Kabel. Ein Knoten ohne Benutzer oder ein eingerichteter ohne Adresse 90 Sekunden nach dem Start öffnet das WLAN ARMOR-SETUP-xxxxxx (Passwort: der Einrichtungscode) und antwortet unter http://192.168.4.1. Nutzen Sie WPA2 oder WPA3 mit einem echten Passwort: Die Clients des Zugangspunkts liegen im selben Netz wie der Broker.",
        "Dans le panneau du nœud, page Wi-Fi, un nœud peut faire deux choses. En point d'accès, il offre son propre réseau, relié à son port Ethernet : donnez à plusieurs nœuds le même nom de réseau, la même sécurité et le même mot de passe, laissez le canal en automatique (chacun prend 1, 6 ou 11 selon sa MAC) et reliez-les au même commutateur, et téléphones et capteurs Wi-Fi voient un réseau avec un serveur DHCP. Ce n'est pas un maillage radio : chaque nœud garde son câble, sert jusqu'à dix clients et a le débit d'un petit microcontrôleur, il convient donc aux capteurs et à la configuration, pas à l'Internet de la maison. En station, le nœud rejoint le Wi-Fi de votre routeur (la page peut chercher les réseaux), ce qui permet à un nœud sans câble de fonctionner. Un nœud sans utilisateur, ou configuré mais sans adresse 90 secondes après le démarrage, ouvre le Wi-Fi ARMOR-SETUP-xxxxxx (mot de passe : le code de configuration) et répond sur http://192.168.4.1. Utilisez WPA2 ou WPA3 avec un vrai mot de passe : les clients du point d'accès sont sur le même réseau que le broker.",
        "Nel pannello del nodo, pagina Wi-Fi, un nodo può fare due cose. Come punto di accesso offre una propria rete, unita alla porta Ethernet: dai a più nodi lo stesso nome di rete, sicurezza e password, lascia il canale in automatico (ognuno sceglie 1, 6 o 11 dal suo MAC) e collegali allo stesso switch, e telefoni e sensori Wi-Fi vedono una rete con un server DHCP. Non è una maglia radio: ogni nodo mantiene il suo cavo, serve fino a dieci client e ha la velocità di un piccolo microcontrollore, quindi serve per sensori e configurazione, non per l'internet di casa. Come stazione, il nodo si collega al Wi-Fi del router (la pagina può cercare le reti), ed è la via di un nodo senza cavo. Un nodo senza utenti, o configurato ma ancora senza indirizzo 90 secondi dopo l'avvio, apre il Wi-Fi ARMOR-SETUP-xxxxxx (password: il codice di configurazione) e risponde su http://192.168.4.1. Usa WPA2 o WPA3 con una password vera: i client del punto di accesso sono nella stessa rete del broker.",
        "ノードのパネルのWi-Fiページで、ノードは2つのことができます。アクセスポイントとして、Ethernetポートに橋渡しした独自のネットワークを提供します。複数のノードに同じネットワーク名・セキュリティ・パスワードを与え、チャンネルは自動のままにし（各ノードがMACから1・6・11を選択）、同じスイッチにつなぐと、スマホやWi-Fiセンサーには1つのDHCPサーバーを持つ1つのネットワークに見えます。無線メッシュではなく、各ノードにケーブルが必要で、最大10クライアントを扱い、速度は小型マイコン並みなので、センサーと設定向けで家庭のインターネット向けではありません。ステーションとしては、ルーターのWi-Fiに参加します（ページでネットワーク検索可）。ケーブルのないノードはこの方法です。ユーザーのないノード、または設定済みなのに起動90秒後もアドレスがないノードは、Wi-Fi ARMOR-SETUP-xxxxxx（パスワードはセットアップコード）を開き、http://192.168.4.1 で応答します。アクセスポイントのクライアントはブローカーと同じネットワークにいるので、WPA2またはWPA3と十分なパスワードを使ってください。",
        "在节点面板的 Wi-Fi 页面，节点可以做两件事。作为接入点，它提供自己的网络并桥接到其以太网口：给多个节点设置相同的网络名称、加密方式和密码，信道保持自动（每个节点按其 MAC 选择 1、6 或 11），再把它们接到同一台交换机，手机和 Wi-Fi 传感器就会看到一个只有一个 DHCP 服务器的网络。这不是无线 Mesh：每个节点仍需接线，最多服务十个客户端，速度相当于小型微控制器，所以适用于传感器和配置，不适合家庭上网。作为终端，节点加入你路由器的 Wi-Fi（页面可搜索网络），没有网线的节点就是这样工作的。没有用户的节点，或已设置但启动 90 秒后仍无地址的节点，会开启 Wi-Fi ARMOR-SETUP-xxxxxx（密码为设置码），并在 http://192.168.4.1 响应。请使用带真实密码的 WPA2 或 WPA3：接入点的客户端与代理处于同一网络。",
        "No painel do nó, página Wi-Fi, um nó pode fazer duas coisas. Como ponto de acesso oferece a sua própria rede, unida à porta Ethernet: dê a vários nós o mesmo nome de rede, segurança e palavra-passe, deixe o canal em automático (cada um escolhe 1, 6 ou 11 pelo seu MAC) e ligue-os ao mesmo comutador, e os telemóveis e sensores Wi-Fi veem uma rede com um servidor DHCP. Não é uma malha de rádio: cada nó mantém o seu cabo, serve até dez clientes e tem a velocidade de um pequeno microcontrolador, por isso serve para sensores e configuração, não para a internet da casa. Como estação, o nó junta-se ao Wi-Fi do seu router (a página pode procurar redes), que é o caminho de um nó sem cabo. Um nó sem utilizador, ou um configurado que 90 segundos depois de arrancar ainda não tem endereço, abre o Wi-Fi ARMOR-SETUP-xxxxxx (palavra-passe: o código de configuração) e responde em http://192.168.4.1. Use WPA2 ou WPA3 com uma palavra-passe a sério: os clientes do ponto de acesso estão na mesma rede que o broker."] },
  { id: "node_fleet", view: "radar", tour: false,
    kw: ["fleet secret|adopt a node|adopt nodes|many nodes|same image|one image|universal image|factory reset|boot button|node name armor-|mac address", "secreto de flota|adoptar un nodo|adoptar nodos|muchos nodos|misma imagen|una imagen|imagen universal|restablecer de fabrica|boton boot|nombre armor-|direccion mac", "flottengeheimnis|knoten uebernehmen|viele knoten|gleiches abbild|ein abbild|universalabbild|werksreset|boot-taste|name armor-|mac-adresse", "secret de flotte|adopter un noeud|adopter des noeuds|beaucoup de noeuds|meme image|une image|image universelle|reinitialisation usine|bouton boot|nom armor-|adresse mac", "segreto di flotta|adottare un nodo|adottare nodi|molti nodi|stessa immagine|un'immagine|immagine universale|ripristino di fabbrica|pulsante boot|nome armor-|indirizzo mac", "フリートシークレット|ノードの採用|多数のノード|同じイメージ|共通イメージ|工場出荷時|bootボタン|armor-という名前|macアドレス", "车队密钥|接管节点|大量节点|同一镜像|通用镜像|恢复出厂|boot按钮|名称armor-|mac地址", "segredo de frota|adotar um no|adotar nos|muitos nos|mesma imagem|uma imagem|imagem universal|reposicao de fabrica|botao boot|nome armor-|endereco mac"],
    q: ["How do I set up many nodes with the same firmware image, and how do I reset one to factory settings?", "¿Cómo preparo muchos nodos con la misma imagen de firmware y cómo restablezco uno de fábrica?", "Wie richte ich viele Knoten mit demselben Firmware-Abbild ein und setze einen auf Werkseinstellungen zurück?", "Comment préparer beaucoup de nœuds avec la même image de firmware et en réinitialiser un aux réglages d'usine ?", "Come preparo molti nodi con la stessa immagine di firmware e come ne ripristino uno alle impostazioni di fabbrica?", "同じファームウェアイメージで多数のノードを準備する方法と、1台を工場出荷時に戻す方法は？", "如何用同一个固件镜像配置大量节点，以及如何把某个节点恢复出厂？", "Como preparo muitos nós com a mesma imagem de firmware e como reponho um de fábrica?"],
    a: ["The firmware is the same for every board of a type and the MAC address tells the boards apart: a new node is called armor- and the last six digits of its MAC until it is named. Flash the one image to every board by USB, then adopt each node over the network: the tool creates its administrator, gives it its identity for the broker and applies the settings every node shares (Wi-Fi, broker, language). With a fleet secret, the set-up code of a board is calculated from its MAC, so no cable or console is needed for each one; the secret is inside the image, so it protects a fleet against the network and not against someone who holds a board. To start a node again, hold the BOOT button for 8 seconds within the first 30 seconds after power-up (it erases the settings and the users) or use Factory reset in its panel. Studio's Look for nodes then finds it and opens its panel.",
        "El firmware es el mismo para todas las placas de un tipo y la dirección MAC las distingue: un nodo nuevo se llama armor- y los seis últimos dígitos de su MAC hasta que se le pone nombre. Graba la misma imagen en todas las placas por USB y luego adopta cada nodo por la red: la herramienta crea su administrador, le da su identidad para el broker y aplica los ajustes que comparten todos (Wi-Fi, broker, idioma). Con un secreto de flota, el código de configuración de una placa se calcula a partir de su MAC, así que no hace falta cable ni consola para cada una; el secreto va dentro de la imagen, por lo que protege a una flota frente a la red y no frente a quien tenga una placa en la mano. Para empezar de nuevo un nodo, mantén pulsado el botón BOOT 8 segundos en los primeros 30 segundos tras dar corriente (borra los ajustes y los usuarios) o usa Restablecer de fábrica en su panel. \"Buscar nodos\" de Studio lo encuentra entonces y abre su panel.",
        "Die Firmware ist für alle Platinen einer Art gleich, und die MAC-Adresse unterscheidet sie: Ein neuer Knoten heißt armor- und die letzten sechs Ziffern seiner MAC, bis er einen Namen bekommt. Flashen Sie das eine Abbild per USB auf alle Platinen und übernehmen Sie dann jeden Knoten über das Netz: Das Werkzeug legt seinen Administrator an, gibt ihm seine Broker-Identität und wendet die gemeinsamen Einstellungen an (WLAN, Broker, Sprache). Mit einem Flottengeheimnis wird der Einrichtungscode einer Platine aus ihrer MAC berechnet, sodass für keine ein Kabel oder eine Konsole nötig ist; das Geheimnis steckt im Abbild und schützt eine Flotte also vor dem Netz, nicht vor jemandem, der eine Platine in der Hand hält. Um einen Knoten neu zu beginnen, halten Sie in den ersten 30 Sekunden nach dem Einschalten die BOOT-Taste 8 Sekunden gedrückt (löscht Einstellungen und Benutzer) oder nutzen Sie Werkseinstellungen im Panel. \"Knoten suchen\" in Studio findet ihn dann und öffnet sein Panel.",
        "Le firmware est le même pour toutes les cartes d'un type et l'adresse MAC les distingue : un nouveau nœud s'appelle armor- et les six derniers chiffres de sa MAC jusqu'à ce qu'on le nomme. Flashez la même image sur toutes les cartes par USB, puis adoptez chaque nœud par le réseau : l'outil crée son administrateur, lui donne son identité pour le broker et applique les réglages communs (Wi-Fi, broker, langue). Avec un secret de flotte, le code de configuration d'une carte se calcule à partir de sa MAC, donc ni câble ni console pour chacune ; le secret est dans l'image, il protège une flotte contre le réseau et non contre quelqu'un qui tient une carte. Pour repartir de zéro avec un nœud, maintenez le bouton BOOT 8 secondes dans les 30 premières secondes après la mise sous tension (efface réglages et utilisateurs) ou utilisez Réinitialisation usine dans son panneau. « Chercher des nœuds » de Studio le trouve alors et ouvre son panneau.",
        "Il firmware è lo stesso per tutte le schede di un tipo e l'indirizzo MAC le distingue: un nodo nuovo si chiama armor- e le ultime sei cifre del suo MAC finché non gli si dà un nome. Scrivi la stessa immagine su tutte le schede via USB, poi adotta ogni nodo in rete: lo strumento crea il suo amministratore, gli dà l'identità per il broker e applica le impostazioni comuni (Wi-Fi, broker, lingua). Con un segreto di flotta, il codice di configurazione di una scheda si calcola dal suo MAC, quindi non servono cavo né console per ciascuna; il segreto è dentro l'immagine, perciò protegge una flotta dalla rete e non da chi ha una scheda in mano. Per ricominciare con un nodo, tieni premuto il pulsante BOOT per 8 secondi nei primi 30 secondi dopo l'accensione (cancella impostazioni e utenti) oppure usa Ripristino di fabbrica nel pannello. \"Cerca nodi\" di Studio lo trova allora e apre il suo pannello.",
        "ファームウェアは同じ種類のすべての基板で共通で、MACアドレスで基板を区別します。新しいノードは名前を付けるまで「armor-」とMACの下6桁で呼ばれます。1つのイメージをUSBで全基板に書き込み、各ノードをネットワーク経由で採用します：ツールが管理者を作成し、ブローカー用のIDを与え、全ノード共通の設定（Wi-Fi、ブローカー、言語）を適用します。フリートシークレットがあれば基板のセットアップコードはMACから計算されるため、1台ずつケーブルやコンソールは不要です。シークレットはイメージ内にあるので、ネットワークからは守れますが、基板を手にした人からは守れません。ノードをやり直すには、電源投入後30秒以内にBOOTボタンを8秒押し続ける（設定とユーザーを消去）か、パネルの「工場出荷時にリセット」を使います。Studioの「ノードを探す」で見つかり、そのパネルが開きます。",
        "同一类型的所有板子固件相同，靠 MAC 地址区分：新节点在命名之前叫 armor- 加 MAC 后六位。用 USB 把同一个镜像刷入每块板子，然后通过网络接管每个节点：工具会创建它的管理员，给它连接代理用的身份，并应用所有节点共用的设置（Wi-Fi、代理、语言）。有了车队密钥，板子的设置码由其 MAC 计算得出，因此不必为每块板接线或连控制台；密钥位于镜像内，所以它能防住网络，却防不住拿到板子的人。要让某个节点重新开始，请在上电后的前 30 秒内按住 BOOT 按钮 8 秒（会清除设置和用户），或使用面板中的“恢复出厂设置”。Studio 的“查找节点”随后就能找到它并打开其面板。",
        "O firmware é o mesmo para todas as placas de um tipo e o endereço MAC distingue-as: um nó novo chama-se armor- e os seis últimos dígitos do MAC até lhe darem nome. Grave a mesma imagem em todas as placas por USB e depois adote cada nó pela rede: a ferramenta cria o seu administrador, dá-lhe a identidade para o broker e aplica as definições que todos partilham (Wi-Fi, broker, idioma). Com um segredo de frota, o código de configuração de uma placa calcula-se a partir do MAC, por isso não é preciso cabo nem consola para cada uma; o segredo vai dentro da imagem, logo protege uma frota contra a rede e não contra quem tenha uma placa na mão. Para recomeçar um nó, mantenha premido o botão BOOT 8 segundos nos primeiros 30 segundos após ligar (apaga as definições e os utilizadores) ou use Repor de fábrica no painel. \"Procurar nós\" do Studio encontra-o então e abre o seu painel."] },
  { id: "second_factor", view: "configuration", tour: false,
    kw: ["second factor|two-step|two factor|2fa|authenticator|recovery code|totp|verification code", "segundo factor|dos pasos|verificacion en dos|autenticador|codigo de recuperacion|codigo de verificacion", "zweiter faktor|zwei-faktor|zweistufig|authenticator|wiederherstellungscode|bestatigungscode", "second facteur|deux etapes|double authentification|authentificateur|code de recuperation|code de verification", "secondo fattore|due passaggi|autenticazione a due|autenticatore|codice di recupero|codice di verifica", "2段階認証|二段階|認証アプリ|リカバリーコード|確認コード", "第二重验证|两步验证|双重验证|验证器|恢复代码|验证码", "segundo fator|dois passos|autenticacao de dois|autenticador|codigo de recuperacao|codigo de verificacao"],
    q: ["How do I turn on the second factor (authenticator app)?", "¿Cómo activo el segundo factor (aplicación autenticadora)?", "Wie schalte ich den zweiten Faktor (Authenticator-App) ein?", "Comment activer le second facteur (application d'authentification) ?", "Come attivo il secondo fattore (app di autenticazione)?", "2 段階認証（認証アプリ）を有効にするには？", "如何启用第二重验证（验证器应用）？", "Como ativo o segundo fator (aplicação de autenticação)?"],
    a: ["Open Configuration > Security. In the second factor card type your password and press \"Set it up\": Studio shows a key and a link. Add the key to an authenticator app (Google Authenticator, Aegis, Authy) on your phone, type the six-digit code it shows and press \"Turn it on\". Studio then shows ten recovery codes ONCE: save them somewhere safe, not on the same phone. From then on signing in asks for the code as a second step. If you lose the phone, use a recovery code (each works once); an administrator can also turn the second factor off for you in Configuration > Users.",
        "Abre Configuración > Seguridad. En la tarjeta del segundo factor escribe tu contraseña y pulsa «Configurarlo»: Studio muestra una clave y un enlace. Añade la clave a una aplicación autenticadora (Google Authenticator, Aegis, Authy) en tu móvil, escribe el código de seis cifras que muestra y pulsa «Activarlo». Studio muestra entonces diez códigos de recuperación UNA sola vez: guárdalos en un lugar seguro, no en el mismo móvil. Desde entonces, entrar pide el código como segundo paso. Si pierdes el móvil, usa un código de recuperación (cada uno vale una vez); un administrador también puede desactivarte el segundo factor en Configuración > Usuarios.",
        "Öffnen Sie Konfiguration > Sicherheit. Geben Sie in der Karte des zweiten Faktors Ihr Passwort ein und drücken Sie „Einrichten“: Studio zeigt einen Schlüssel und einen Link. Fügen Sie den Schlüssel einer Authenticator-App (Google Authenticator, Aegis, Authy) auf Ihrem Handy hinzu, tippen Sie den sechsstelligen Code ein und drücken Sie „Einschalten“. Studio zeigt dann EINMAL zehn Wiederherstellungscodes: Bewahren Sie sie sicher auf, nicht auf demselben Handy. Danach verlangt die Anmeldung den Code als zweiten Schritt. Bei Verlust des Handys nutzen Sie einen Wiederherstellungscode (jeder gilt einmal); ein Administrator kann den zweiten Faktor auch unter Konfiguration > Benutzer für Sie ausschalten.",
        "Ouvrez Configuration > Sécurité. Dans la carte du second facteur, saisissez votre mot de passe et appuyez sur « Le configurer » : Studio montre une clé et un lien. Ajoutez la clé à une application d'authentification (Google Authenticator, Aegis, Authy) sur votre téléphone, saisissez le code à six chiffres et appuyez sur « L'activer ». Studio montre alors dix codes de récupération UNE seule fois : gardez-les en lieu sûr, pas sur le même téléphone. Ensuite, la connexion demande le code en seconde étape. Si vous perdez le téléphone, utilisez un code de récupération (chacun sert une fois) ; un administrateur peut aussi désactiver le second facteur dans Configuration > Utilisateurs.",
        "Apri Configurazione > Sicurezza. Nella scheda del secondo fattore digita la tua password e premi «Configuralo»: Studio mostra una chiave e un collegamento. Aggiungi la chiave a un'app di autenticazione (Google Authenticator, Aegis, Authy) sul telefono, digita il codice di sei cifre e premi «Attivalo». Studio mostra poi dieci codici di recupero UNA sola volta: salvali in un posto sicuro, non sullo stesso telefono. Da allora l'accesso chiede il codice come secondo passaggio. Se perdi il telefono, usa un codice di recupero (ognuno vale una volta); un amministratore può anche disattivarti il secondo fattore in Configurazione > Utenti.",
        "「設定 > セキュリティ」を開き、2 段階認証のカードでパスワードを入力して「設定する」を押すと、Studio がキーとリンクを表示します。スマホの認証アプリ（Google Authenticator、Aegis、Authy）にキーを追加し、表示された 6 桁のコードを入力して「有効にする」を押します。Studio は 10 個のリカバリーコードを一度だけ表示するので、同じスマホ以外の安全な場所に保管してください。以降、サインインでは 2 段階目としてコードを求められます。スマホを失くしたらリカバリーコード（各 1 回）を使います。管理者が「設定 > ユーザー」で 2 段階認証を無効にすることもできます。",
        "打开“配置 > 安全”。在第二重验证卡片中输入密码并点击“开始设置”：Studio 会显示一个密钥和一个链接。把密钥添加到手机上的验证器应用（Google Authenticator、Aegis、Authy），输入它显示的六位代码并点击“启用”。随后 Studio 只会显示一次十个恢复代码：请保存在安全的地方，不要放在同一部手机上。此后登录会要求输入代码作为第二步。若丢失手机，使用恢复代码（每个仅一次）；管理员也可以在“配置 > 用户”中为您停用第二重验证。",
        "Abra Configuração > Segurança. No cartão do segundo fator escreva a sua palavra-passe e carregue em «Configurá-lo»: o Studio mostra uma chave e uma ligação. Adicione a chave a uma aplicação de autenticação (Google Authenticator, Aegis, Authy) no telemóvel, escreva o código de seis algarismos e carregue em «Ativá-lo». O Studio mostra então dez códigos de recuperação UMA só vez: guarde-os num sítio seguro, não no mesmo telemóvel. A partir daí a entrada pede o código como segundo passo. Se perder o telemóvel, use um código de recuperação (cada um vale uma vez); um administrador também pode desativar-lhe o segundo fator em Configuração > Utilizadores."] },
  { id: "remote_access", view: "configuration", tour: false,
    kw: ["outside the house|from outside|remote access|away from home|mobile data|public address|port forward|router port|vpn|wireguard|reverse proxy|https certificate", "fuera de casa|desde fuera|acceso remoto|datos moviles|direccion publica|abrir puertos|puerto del router|vpn|wireguard|proxy inverso|certificado https", "von auberhalb|ausserhalb|fernzugriff|mobile daten|offentliche adresse|portweiterleitung|router port|vpn|wireguard|reverse-proxy|https-zertifikat", "depuis l'exterieur|hors de la maison|acces a distance|donnees mobiles|adresse publique|redirection de port|port du routeur|vpn|wireguard|proxy inverse|certificat https", "da fuori casa|dall'esterno|accesso remoto|dati mobili|indirizzo pubblico|inoltro di porta|porta del router|vpn|wireguard|reverse proxy|certificato https", "家の外|外出先|リモートアクセス|モバイルデータ|公開アドレス|ポート転送|ルーターのポート|vpn|wireguard|リバースプロキシ|https証明書", "家外|外网访问|远程访问|移动数据|公网地址|端口转发|路由器端口|vpn|wireguard|反向代理|https证书", "fora de casa|a partir de fora|acesso remoto|dados moveis|endereco publico|redirecionamento de porta|porta do router|vpn|wireguard|proxy inverso|certificado https"],
    q: ["How do I use A.R.M.O.R. from outside the house?", "¿Cómo uso A.R.M.O.R. desde fuera de casa?", "Wie nutze ich A.R.M.O.R. von außerhalb des Hauses?", "Comment utiliser A.R.M.O.R. depuis l'extérieur ?", "Come uso A.R.M.O.R. da fuori casa?", "家の外から A.R.M.O.R. を使うには？", "如何在家外使用 A.R.M.O.R.？", "Como uso o A.R.M.O.R. de fora de casa?"],
    a: ["Open the server to the Internet through ONE door only: a reverse proxy with a valid certificate (the TLS profile of the installation) on a single port of the router, or a VPN. Never publish the MQTT broker or the nodes. Then: 1) in Configuration > Security (administrator) set the trusted proxy so the server sees the real address of each visitor, 2) turn on the second factor for every account and, if you want, require it from outside, 3) choose what a session from outside may do (everything, operate the alarm only, or only look), 4) from a phone on mobile data press \"Check how the server sees me\": it must say \"from outside\". Critical actions (users, firmware updates) ask for your password again when you are outside, and Security lists your open sessions so you can end any you do not recognise.",
        "Abre el servidor a Internet por UNA sola puerta: un proxy inverso con certificado válido (el perfil TLS de la instalación) en un único puerto del router, o una VPN. Nunca publiques el broker MQTT ni los nodos. Después: 1) en Configuración > Seguridad (administrador) indica el proxy de confianza para que el servidor vea la dirección real de cada visitante, 2) activa el segundo factor en cada cuenta y, si quieres, exígelo desde fuera, 3) elige qué puede hacer una sesión desde fuera (todo, solo manejar la alarma o solo mirar), 4) desde un móvil con datos pulsa «Comprobar cómo me ve el servidor»: debe decir «desde fuera». Las acciones críticas (usuarios, actualizaciones de firmware) piden tu contraseña de nuevo cuando estás fuera, y Seguridad lista tus sesiones abiertas para que cierres las que no reconozcas.",
        "Öffnen Sie den Server nur durch EINE Tür ins Internet: einen Reverse-Proxy mit gültigem Zertifikat (das TLS-Profil der Installation) an einem einzigen Router-Port oder ein VPN. Veröffentlichen Sie nie den MQTT-Broker oder die Knoten. Dann: 1) Tragen Sie in Konfiguration > Sicherheit (Administrator) den vertrauenswürdigen Proxy ein, damit der Server die echte Adresse jedes Besuchers sieht, 2) schalten Sie den zweiten Faktor für jedes Konto ein und verlangen Sie ihn bei Bedarf von außen, 3) wählen Sie, was eine Sitzung von außen darf (alles, nur den Alarm bedienen oder nur ansehen), 4) drücken Sie auf einem Handy mit Mobilfunk „Prüfen, wie der Server mich sieht“: Es muss „von außerhalb“ sagen. Kritische Aktionen (Benutzer, Firmware-Updates) verlangen von außen erneut Ihr Passwort, und Sicherheit listet Ihre offenen Sitzungen, damit Sie unbekannte beenden.",
        "Ouvrez le serveur à Internet par UNE seule porte : un proxy inverse avec certificat valide (le profil TLS de l'installation) sur un seul port du routeur, ou un VPN. Ne publiez jamais le broker MQTT ni les nœuds. Ensuite : 1) dans Configuration > Sécurité (administrateur), indiquez le proxy de confiance pour que le serveur voie l'adresse réelle de chaque visiteur, 2) activez le second facteur pour chaque compte et, si vous voulez, exigez-le depuis l'extérieur, 3) choisissez ce qu'une session extérieure peut faire (tout, seulement manœuvrer l'alarme, ou seulement regarder), 4) depuis un téléphone en données mobiles, appuyez sur « Vérifier comment le serveur me voit » : il doit dire « depuis l'extérieur ». Les actions critiques (utilisateurs, mises à jour de firmware) redemandent votre mot de passe depuis l'extérieur, et Sécurité liste vos sessions ouvertes pour fermer celles que vous ne reconnaissez pas.",
        "Apri il server a Internet da UNA sola porta: un reverse proxy con certificato valido (il profilo TLS dell'installazione) su una sola porta del router, o una VPN. Non pubblicare mai il broker MQTT né i nodi. Poi: 1) in Configurazione > Sicurezza (amministratore) indica il proxy attendibile perché il server veda l'indirizzo reale di ogni visitatore, 2) attiva il secondo fattore su ogni account e, se vuoi, richiedilo da fuori, 3) scegli cosa può fare una sessione da fuori (tutto, solo usare l'allarme o solo guardare), 4) da un telefono con dati mobili premi «Controlla come mi vede il server»: deve dire «da fuori». Le azioni critiche (utenti, aggiornamenti del firmware) chiedono di nuovo la password quando sei fuori, e Sicurezza elenca le tue sessioni aperte per chiudere quelle che non riconosci.",
        "サーバーをインターネットに公開するのは「1 つの入口」だけにします。有効な証明書付きのリバースプロキシ（インストールの TLS プロファイル）をルーターの 1 つのポートに置くか、VPN を使います。MQTT ブローカーやノードは決して公開しないでください。次に、1) 「設定 > セキュリティ」（管理者）で信頼するプロキシを設定し、サーバーが訪問者の本当のアドレスを見られるようにします。2) すべてのアカウントで 2 段階認証を有効にし、必要なら外部からは必須にします。3) 外部セッションにできること（すべて／アラーム操作のみ／閲覧のみ）を選びます。4) モバイルデータのスマホで「サーバーからの見え方を確認」を押すと「外部から」と表示されるはずです。家の外では重要な操作（ユーザー、ファームウェア更新）でパスワードを再入力し、「セキュリティ」で開いているセッションを確認して心当たりのないものを終了できます。",
        "只通过“一个入口”向互联网开放服务器：在路由器的单个端口上放置带有效证书的反向代理（安装的 TLS 配置），或使用 VPN。绝不要公开 MQTT 代理或节点。然后：1) 在“配置 > 安全”（管理员）中设置受信任的代理，让服务器看到每位访问者的真实地址；2) 为每个账户启用第二重验证，需要时要求从外部登录时必须使用；3) 选择来自外部的会话可执行的操作（全部、仅操作报警或仅查看）；4) 用移动数据的手机点击“检查服务器如何看待我”：应显示“来自外部”。在家外时，关键操作（用户、固件更新）会再次要求输入密码；“安全”页会列出您已打开的会话，便于结束不认识的会话。",
        "Abra o servidor à Internet por UMA só porta: um proxy inverso com certificado válido (o perfil TLS da instalação) numa única porta do router, ou uma VPN. Nunca publique o broker MQTT nem os nós. Depois: 1) em Configuração > Segurança (administrador) indique o proxy de confiança para o servidor ver o endereço real de cada visitante, 2) ative o segundo fator em cada conta e, se quiser, exija-o de fora, 3) escolha o que pode fazer uma sessão de fora (tudo, só manobrar o alarme ou só olhar), 4) num telemóvel com dados móveis carregue em «Verificar como o servidor me vê»: deve dizer «de fora». As ações críticas (utilizadores, atualizações de firmware) pedem de novo a palavra-passe quando está fora, e Segurança lista as suas sessões abertas para fechar as que não reconhecer."] },
  { id: "vpn_node_panels", view: "configuration", tour: false,
    kw: ["wireguard|vpn device|add phone to vpn|qr code vpn|dynamic dns|duckdns|cloudflare dns|node panel from outside|open node panel|node certificate|fingerprint", "wireguard|dispositivo vpn|anadir movil a la vpn|codigo qr vpn|dns dinamico|duckdns|cloudflare dns|panel de nodo desde fuera|abrir panel de nodo|certificado del nodo|huella", "wireguard|vpn-geraet|handy zum vpn|qr-code vpn|dynamisches dns|duckdns|cloudflare dns|knoten-panel von aussen|knoten-panel oeffnen|zertifikat des knotens|fingerabdruck", "wireguard|appareil vpn|ajouter telephone au vpn|code qr vpn|dns dynamique|duckdns|cloudflare dns|panneau du noeud depuis l'exterieur|ouvrir panneau noeud|certificat du noeud|empreinte", "wireguard|dispositivo vpn|aggiungere telefono alla vpn|codice qr vpn|dns dinamico|duckdns|cloudflare dns|pannello del nodo da fuori|aprire pannello nodo|certificato del nodo|impronta", "wireguard|vpn 端末|vpn にスマホを追加|vpn qr コード|ダイナミック dns|duckdns|cloudflare dns|外からノードのパネル|ノードパネルを開く|ノードの証明書|フィンガープリント", "wireguard|vpn 设备|把手机加入 vpn|vpn 二维码|动态 dns|duckdns|cloudflare dns|从外面打开节点面板|打开节点面板|节点证书|指纹", "wireguard|dispositivo vpn|adicionar telemovel a vpn|codigo qr vpn|dns dinamico|duckdns|cloudflare dns|painel do no de fora|abrir painel do no|certificado do no|impressao digital"],
    q: ["How do I add a phone to the WireGuard VPN, keep a dynamic DNS name and open a node panel?", "¿Cómo añado un móvil a la VPN WireGuard, mantengo un DNS dinámico y abro el panel de un nodo?", "Wie füge ich ein Handy zum WireGuard-VPN hinzu, halte ein dynamisches DNS aktuell und öffne ein Knoten-Panel?", "Comment ajouter un téléphone au VPN WireGuard, garder un DNS dynamique et ouvrir le panneau d'un nœud ?", "Come aggiungo un telefono alla VPN WireGuard, mantengo un DNS dinamico e apro il pannello di un nodo?", "WireGuard VPN にスマホを追加し、ダイナミック DNS を保ち、ノードパネルを開くには？", "如何把手机加入 WireGuard VPN、保持动态 DNS 并打开节点面板？", "Como adiciono um telemóvel à VPN WireGuard, mantenho um DNS dinâmico e abro o painel de um nó?"],
    a: ["Everything is in Configuration > Security (administrators), no file to edit. VPN: type the name or address your phone will use, the port and the network of the house, press Set up the VPN, forward that UDP port on your router to the machine, then Add a device and scan its QR code with the WireGuard app (the code holds a private key: close it afterwards). Name: choose DuckDNS, Cloudflare or an address to call, and the machine keeps the name pointing at your house when your provider changes the address. Node panels: register the node's address inside the house; if it uses HTTPS, look at its certificate, compare the fingerprint with the one in the node's own panel (About) and trust it; then Open panel works from outside, through the server, and the node is never published.",
        "Todo está en Configuración > Seguridad (administradores), sin editar ningún archivo. VPN: escribe el nombre o dirección que usará el móvil, el puerto y la red de la casa, pulsa Configurar la VPN, redirige ese puerto UDP del router a la máquina y luego Añadir un dispositivo y escanea su código QR con la app WireGuard (el código lleva una clave privada: ciérralo después). Nombre: elige DuckDNS, Cloudflare o una dirección a la que llamar, y la máquina mantiene el nombre apuntando a tu casa cuando el operador cambia la dirección. Paneles de nodos: registra la dirección del nodo dentro de casa; si usa HTTPS, mira su certificado, compara la huella con la del propio panel del nodo (Acerca de) y confía en él; después Abrir panel funciona desde fuera, a través del servidor, y el nodo nunca se publica.",
        "Alles steht unter Konfiguration > Sicherheit (Administratoren), ohne eine Datei zu bearbeiten. VPN: Namen oder Adresse für das Handy, Port und Netz des Hauses eintragen, VPN einrichten drücken, diesen UDP-Port am Router an die Maschine weiterleiten, dann Gerät hinzufügen und seinen QR-Code mit der WireGuard-App scannen (der Code enthält einen privaten Schlüssel: danach schließen). Name: DuckDNS, Cloudflare oder eine aufzurufende Adresse wählen; die Maschine hält den Namen auf Ihr Haus gerichtet, wenn der Anbieter die Adresse ändert. Knoten-Panels: Adresse des Knotens im Haus eintragen; bei HTTPS das Zertifikat ansehen, den Fingerabdruck mit dem im Panel des Knotens (Info) vergleichen und vertrauen; dann funktioniert Panel öffnen von außen über den Server, und der Knoten wird nie veröffentlicht.",
        "Tout se trouve dans Configuration > Sécurité (administrateurs), sans modifier de fichier. VPN : saisissez le nom ou l'adresse que le téléphone utilisera, le port et le réseau de la maison, appuyez sur Configurer le VPN, redirigez ce port UDP du routeur vers la machine, puis Ajouter un appareil et scannez son code QR avec l'application WireGuard (le code contient une clé privée : fermez-le ensuite). Nom : choisissez DuckDNS, Cloudflare ou une adresse à appeler, et la machine garde le nom pointé vers votre maison quand le fournisseur change l'adresse. Panneaux des nœuds : enregistrez l'adresse du nœud dans la maison ; s'il utilise HTTPS, regardez son certificat, comparez l'empreinte avec celle du panneau du nœud (À propos) et faites-lui confiance ; Ouvrir le panneau fonctionne ensuite depuis l'extérieur, via le serveur, et le nœud n'est jamais publié.",
        "Tutto è in Configurazione > Sicurezza (amministratori), senza modificare file. VPN: scrivi il nome o l'indirizzo che userà il telefono, la porta e la rete della casa, premi Configura la VPN, inoltra quella porta UDP del router alla macchina, poi Aggiungi un dispositivo e scansiona il suo codice QR con l'app WireGuard (il codice contiene una chiave privata: chiudilo dopo). Nome: scegli DuckDNS, Cloudflare o un indirizzo da chiamare, e la macchina mantiene il nome puntato a casa tua quando l'operatore cambia l'indirizzo. Pannelli dei nodi: registra l'indirizzo del nodo in casa; se usa HTTPS, guarda il suo certificato, confronta l'impronta con quella del pannello del nodo (Informazioni) e fidati; poi Apri pannello funziona da fuori, tramite il server, e il nodo non viene mai pubblicato.",
        "すべて「設定 > セキュリティ」（管理者）にあり、ファイル編集は不要です。VPN：スマホが使う名前またはアドレス、ポート、家のネットワークを入力して「VPN を設定」を押し、ルーターでその UDP ポートをこのマシンに転送し、「端末を追加」して WireGuard アプリで QR コードを読み取ります（QR には秘密鍵が含まれるので、読み取り後に閉じます）。名前：DuckDNS、Cloudflare、または呼び出せるアドレスを選ぶと、プロバイダーがアドレスを変えても名前が家を指し続けます。ノードパネル：家の中のノードのアドレスを登録し、HTTPS なら証明書を確認してフィンガープリントをノードのパネル（情報）のものと比べて信頼します。以後は「パネルを開く」で外からサーバー経由で開け、ノードは公開されません。",
        "全部在“配置 > 安全”（管理员）中完成，无需编辑文件。VPN：填写手机使用的名称或地址、端口和家庭网络，点“设置 VPN”，在路由器上把该 UDP 端口转发到本机，然后“添加设备”，用 WireGuard 应用扫描二维码（二维码含私钥，用完请关闭）。域名：选择 DuckDNS、Cloudflare 或可调用的地址，运营商更换地址后，本机会让域名始终指向您家。节点面板：登记节点在家中的地址；若使用 HTTPS，请查看证书，把指纹与节点面板（关于）中的比对后再信任；之后“打开面板”即可在家外通过服务器使用，节点不会被公开。",
        "Tudo está em Configuração > Segurança (administradores), sem editar ficheiros. VPN: escreva o nome ou endereço que o telemóvel usará, a porta e a rede da casa, carregue em Configurar a VPN, reencaminhe essa porta UDP do router para a máquina e depois Adicionar um dispositivo e leia o seu código QR com a app WireGuard (o código leva uma chave privada: feche-o depois). Nome: escolha DuckDNS, Cloudflare ou um endereço a chamar, e a máquina mantém o nome a apontar para a sua casa quando o operador muda o endereço. Painéis dos nós: registe o endereço do nó dentro de casa; se usar HTTPS, veja o certificado, compare a impressão digital com a do painel do nó (Acerca de) e confie nele; depois Abrir painel funciona de fora, através do servidor, e o nó nunca é publicado."] },
  { id: "zigbee_network", view: "alarmPanels", tour: false,
    kw: ["network zigbee coordinator|zigbee over ethernet|zigbee coordinator on the network|zigbee coordinator of the network|slzb|uzg-01|zigbee tcp|zigbee without radio|ethernet zigbee coordinator", "coordinador zigbee de red|zigbee por ethernet|coordinador zigbee en la red|coordinador zigbee de la red|slzb|uzg-01|zigbee por tcp|zigbee sin radio|coordinador zigbee ethernet", "zigbee koordinator im netzwerk|zigbee ueber ethernet|netzwerk koordinator zigbee|slzb|uzg-01|zigbee tcp|zigbee ohne funkmodul|zigbee koordinator netzwerk", "coordinateur zigbee reseau|zigbee par ethernet|coordinateur zigbee sur le reseau|coordinateur zigbee du reseau|slzb|uzg-01|zigbee tcp|zigbee sans radio", "coordinatore zigbee di rete|zigbee via ethernet|coordinatore zigbee in rete|coordinatore zigbee della rete|slzb|uzg-01|zigbee tcp|zigbee senza radio", "ネットワークzigbeeコーディネーター|zigbeeコーディネーター|ネットワーク上のzigbee|slzb|uzg-01|zigbee tcp|ネットワーク経由のzigbee", "网络zigbee协调器|网络上的zigbee协调器|zigbee以太网|slzb|uzg-01|zigbee tcp|无线电模块的zigbee", "coordenador zigbee de rede|zigbee por ethernet|coordenador zigbee na rede|coordenador zigbee da rede|slzb|uzg-01|zigbee tcp|zigbee sem radio"],
    q: ["Can an alarm node use a Zigbee coordinator on the network?", "¿Puede una central de alarma usar un coordinador Zigbee de la red?", "Kann eine Alarmzentrale einen Zigbee-Koordinator im Netzwerk nutzen?", "Une centrale d'alarme peut-elle utiliser un coordinateur Zigbee du réseau ?", "Una centrale d'allarme può usare un coordinatore Zigbee di rete?", "警報ノードはネットワーク上のZigbeeコーディネーターを使えますか？", "报警节点可以使用网络上的 Zigbee 协调器吗？", "Uma central de alarme pode usar um coordenador Zigbee da rede?"],
    a: ["Yes. Besides the Zigbee module on its board, the alarm node can listen to a Zigbee coordinator on the network (for example SMLIGHT SLZB-06P7 or ZigStar UZG-01, over Ethernet or PoE). In the node's own panel, in the Zigbee card, type the address and the port of the coordinator (usually 6638) instead of using the local radio; only one of the two is used.",
        "Sí. Además del módulo Zigbee de su placa, la central de alarma puede escuchar a un coordinador Zigbee de la red (por ejemplo SMLIGHT SLZB-06P7 o ZigStar UZG-01, por Ethernet o PoE). En el panel del propio nodo, en la tarjeta de Zigbee, escribe la dirección y el puerto del coordinador (normalmente 6638) en lugar de usar la radio local; solo se usa una de las dos.",
        "Ja. Neben dem Zigbee-Modul auf ihrer Platine kann die Alarmzentrale einen Zigbee-Koordinator im Netzwerk abhören (zum Beispiel SMLIGHT SLZB-06P7 oder ZigStar UZG-01, über Ethernet oder PoE). Tragen Sie im Panel des Knotens in der Zigbee-Karte Adresse und Port des Koordinators ein (meist 6638), statt das lokale Funkmodul zu nutzen; es wird nur eines von beiden verwendet.",
        "Oui. En plus du module Zigbee de sa carte, la centrale d'alarme peut écouter un coordinateur Zigbee du réseau (par exemple SMLIGHT SLZB-06P7 ou ZigStar UZG-01, par Ethernet ou PoE). Dans le panneau du nœud, dans la carte Zigbee, saisissez l'adresse et le port du coordinateur (généralement 6638) au lieu d'utiliser la radio locale ; un seul des deux est utilisé.",
        "Sì. Oltre al modulo Zigbee della sua scheda, la centrale d'allarme può ascoltare un coordinatore Zigbee della rete (per esempio SMLIGHT SLZB-06P7 o ZigStar UZG-01, via Ethernet o PoE). Nel pannello del nodo, nella scheda Zigbee, scrivi l'indirizzo e la porta del coordinatore (di solito 6638) invece di usare la radio locale; se ne usa solo una delle due.",
        "はい。基板上のZigbeeモジュールのほかに、警報ノードはネットワーク上のZigbeeコーディネーター（例：SMLIGHT SLZB-06P7、ZigStar UZG-01。Ethernet/PoE接続）にも接続できます。ノード自身のパネルのZigbeeカードで、ローカル無線の代わりにコーディネーターのアドレスとポート（通常6638）を入力します。使われるのはどちらか一方だけです。",
        "可以。除了板上的 Zigbee 模块，报警节点还可以连接网络上的 Zigbee 协调器（例如 SMLIGHT SLZB-06P7 或 ZigStar UZG-01，通过以太网或 PoE）。在节点自己的面板的 Zigbee 卡片中，填入协调器的地址和端口（通常是 6638），而不使用本地无线电；两者只会使用其中一个。",
        "Sim. Além do módulo Zigbee da sua placa, a central de alarme pode ouvir um coordenador Zigbee da rede (por exemplo SMLIGHT SLZB-06P7 ou ZigStar UZG-01, por Ethernet ou PoE). No painel do próprio nó, no cartão Zigbee, escreva o endereço e a porta do coordenador (normalmente 6638) em vez de usar o rádio local; só se usa um dos dois."] },
];
